import type { NextRequest } from 'next/server'
import type { ApiPost, CreatePostBody } from '@/lib/types'

export async function GET() {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  const body = (await request.json()) as CreatePostBody
  const { title, content } = body

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

import type { NextRequest } from 'next/server'
import type { ApiPost, UpdatePostBody } from '@/lib/types'

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params

  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const body = (await request.json()) as UpdatePostBody
  const { title, content } = body

  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

